def boundary_transform(arr):
 h,w=arr.shape
 markers=list(zip(*np.where(arr==6)))
 start=markers[0]
 # BFS from marker through 8 cells; preserve marker itself
 seen={start}; q=deque([start])
 while q:
  r,c=q.popleft()
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and arr[rr,cc]==8 and (rr,cc) not in seen:
    seen.add((rr,cc));q.append((rr,cc))
 out=np.where(arr==1,8,arr) # remove all 1 initially
 for r,c in seen:
  if arr[r,c]==8:
   out[r,c]=8
   # if adjacent (8-neighborhood) to any not-in-region/outside or array boundary -> mark7
   border=(r==0 or r==h-1 or c==0 or c==w-1)
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     if dr==dc==0:continue
     rr,cc=r+dr,c+dc
     if not(0<=rr<h and 0<=cc<w) or (rr,cc) not in seen:
      border=True
   if border:out[r,c]=7
 # preserve 1 only when in neighboring boundary? set 1 if any orth/diag neighbor seen
 for r,c in zip(*np.where(arr==1)):
  if any((r+dr,c+dc) in seen for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc)):
   out[r,c]=1
 return out

